import{_ as a,a0 as l,w as p,s as r,I as i,x as t,a1 as n,A as o,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"如何在 Linux 中快速監控多個主機 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中快速監控多個主機 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中快速監控多個主機 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中快速監控多個主機 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180312 How To Quickly Monitor Multiple Hosts In Linux","title":"如何在 Linux 中快速監控多個主機","tag":"201805","desc":""},"relativePath":"201805/20180312 How To Quickly Monitor Multiple Hosts In Linux.md","filePath":"[post].md"}'),h={name:"201805/20180312 How To Quickly Monitor Multiple Hosts In Linux.md"};function u(c,s,g,k,b,w){const e=l("Link");return p(),r("div",null,[s[16]||(s[16]=i("h1",{id:"如何在-linux-中快速監控多個主機",tabindex:"-1"},[t("如何在 Linux 中快速監控多個主機 "),i("a",{class:"header-anchor",href:"#如何在-linux-中快速監控多個主機","aria-label":"Permalink to “如何在 Linux 中快速監控多個主機”"},"​")],-1)),s[17]||(s[17]=i("p",null,[i("img",{src:"https://www.ostechnix.com/wp-content/uploads/2018/03/rwho-1-720x340.png",alt:""})],-1)),i("p",null,[s[1]||(s[1]=t("有很多監控工具可用來監控本地和遠程 Linux 系統，一個很好的例子是 ",-1)),n(e,{href:"https://www.ostechnix.com/cockpit-monitor-administer-linux-servers-via-web-browser/"},{default:o(()=>[...s[0]||(s[0]=[t("Cockpit",-1)])]),_:1}),s[2]||(s[2]=t("。但是，這些工具的安裝和使用比較複雜，至少對於新手管理員來説是這樣。新手管理員可能需要花一些時間來弄清楚如何配置這些工具來監視系統。如果你想要以快速且粗略地在局域網中一次監控多台主機，你可能需要了解一下 “rwho” 工具。只要安裝了 rwho 實用程序，它將立即快速地監控本地和遠程系統。你什麼都不用配置！你所要做的就是在要監視的系統上安裝 “rwho” 工具。",-1))]),s[18]||(s[18]=d(`<p>請不要將 rwho 視為功能豐富且完整的監控工具。這只是一個簡單的工具，它只監視遠程系統的“正常運行時間”（<code>uptime</code>），“負載”（<code>load</code>）和<strong>登錄的用户</strong>。使用 “rwho” 使用程序，我們可以發現誰在哪台計算機上登錄；一個被監視的計算機的列表，列出了正常運行時間（自上次重新啓動以來的時間）；有多少用户登錄了；以及在過去的 1、5、15 分鐘的平均負載。不多不少！而且，它只監視同一子網中的系統。因此，它非常適合小型和家庭辦公網絡。</p><h3 id="在-linux-中監控多台主機" tabindex="-1">在 Linux 中監控多台主機 <a class="header-anchor" href="#在-linux-中監控多台主機" aria-label="Permalink to “在 Linux 中監控多台主機”">​</a></h3><p>讓我來解釋一下 <code>rwho</code> 是如何工作的。每個在網絡上使用 <code>rwho</code> 的系統都將廣播關於它自己的信息，其他計算機可以使用 <code>rwhod</code> 守護進程來訪問這些信息。因此，網絡上的每台計算機都必須安裝 <code>rwho</code>。此外，為了分發或訪問其他主機的信息，必須允許 <code>rwho</code> 端口（例如端口 <code>513/UDP</code>）通過防火牆/路由器。</p><p>好的，讓我們來安裝它。</p><p>我在 Ubuntu 16.04 LTS 服務器上進行了測試，<code>rwho</code> 在默認倉庫中可用，所以，我們可以使用像下面這樣的 APT 軟件包管理器來安裝它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install rwho</span></span></code></pre></div><p>在基於 RPM 的系統如 CentOS、 Fedora、 RHEL 上，使用以下命令來安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install rwho</span></span></code></pre></div><p>如果你在防火牆/路由器之後，確保你已經允許使用 rwhod 513 端口。另外，使用命令驗證 <code>rwhod</code> 守護進程是否正在運行：</p><p>$ sudo systemctl status rwhod</p><p>如果它尚未啓動，運行以下命令啓用並啓動 <code>rwhod</code> 服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable rwhod</span></span>
<span class="line"><span>$ sudo systemctl start rwhod</span></span></code></pre></div><p>現在是時候來監視系統了。運行以下命令以發現誰在哪台計算機上登錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rwho</span></span>
<span class="line"><span>ostechni ostechnix:pts/5 Mar 12 17:41</span></span>
<span class="line"><span>root server:pts/0 Mar 12 17:42</span></span></code></pre></div><p>正如你所看到的，目前我的局域網中有兩個系統。本地系統用户是 <code>ostechnix</code> （Ubuntu 16.04 LTS），遠程系統的用户是 <code>root</code> （CentOS 7）。可能你已經猜到了，<code>rwho</code> 與 <code>who</code> 命令相似，但它會監視遠程系統。</p><p>而且，我們可以使用以下命令找到網絡上所有正在運行的系統的正常運行時間：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ruptime</span></span>
<span class="line"><span>ostechnix up 2:17, 1 user, load 0.09, 0.03, 0.01</span></span>
<span class="line"><span>server up 1:54, 1 user, load 0.00, 0.01, 0.05</span></span></code></pre></div><p>這裏，<code>ruptime</code>（類似於 <code>uptime</code> 命令）顯示了我的 Ubuntu（本地） 和 CentOS（遠程）系統的總運行時間。明白了嗎？棒極了！以下是我的 Ubuntu 16.04 LTS 系統的示例屏幕截圖：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/rwho.png" alt=""></p><p>你可以在以下位置找到有關局域網中所有其他機器的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls /var/spool/rwho/</span></span>
<span class="line"><span>whod.ostechnix whod.server</span></span></code></pre></div><p>它很小，但卻非常有用，可以發現誰在哪台計算機上登錄，以及正常運行時間和系統負載詳情。</p><p><strong>建議閲讀：</strong></p><p>請注意，這種方法有一個嚴重的漏洞。由於有關每台計算機的信息都通過網絡進行廣播，因此該子網中的每個人都可能獲得此信息。通常情況下可以，但另一方面，當有關網絡的信息分發給非授權用户時，這可能是不必要的副作用。因此，強烈建議在受信任和受保護的局域網中使用它。</p><p>更多的信息，查找 man 手冊頁。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man rwho</span></span></code></pre></div><p>好了，這就是全部了。更多好東西要來了，敬請期待！</p><p>乾杯！</p><hr>`,29)),i("p",null,[s[4]||(s[4]=t("via: ",-1)),n(e,{href:"https://www.ostechnix.com/how-to-quickly-monitor-multiple-hosts-in-linux/"},{default:o(()=>[...s[3]||(s[3]=[t("https://www.ostechnix.com/how-to-quickly-monitor-multiple-hosts-in-linux/",-1)])]),_:1})]),i("p",null,[s[8]||(s[8]=t("作者：",-1)),n(e,{href:"https://www.ostechnix.com/author/sk/"},{default:o(()=>[...s[5]||(s[5]=[t("SK",-1)])]),_:1}),s[9]||(s[9]=t(" 譯者：",-1)),n(e,{href:"https://github.com/MjSeven"},{default:o(()=>[...s[6]||(s[6]=[t("MjSeven",-1)])]),_:1}),s[10]||(s[10]=t(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:o(()=>[...s[7]||(s[7]=[t("wxy",-1)])]),_:1})]),i("p",null,[s[13]||(s[13]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[11]||(s[11]=[t("LCTT",-1)])]),_:1}),s[14]||(s[14]=t(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:o(()=>[...s[12]||(s[12]=[t("Linux中國",-1)])]),_:1}),s[15]||(s[15]=t(" 榮譽推出",-1))])])}const C=a(h,[["render",u]]);export{f as __pageData,C as default};
